package com.splitmate.api; import com.splitmate.api.ApiDtos.*;import com.splitmate.domain.User;import com.splitmate.service.SplitMateService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/households") public class HouseholdController{private final SplitMateService s;public HouseholdController(SplitMateService s){this.s=s;}private User me(Authentication a){return s.current(a.getName());}@GetMapping public List<HouseholdView> list(Authentication a){return s.listHouseholds(me(a));}@PostMapping public HouseholdView create(@Valid @RequestBody CreateHousehold x,Authentication a){return s.createHousehold(x.name(),me(a));}@GetMapping("/{id}")public HouseholdView get(@PathVariable Long id,Authentication a){return s.household(id,me(a));}@PostMapping("/{id}/members")public HouseholdView add(@PathVariable Long id,@Valid @RequestBody AddMember x,Authentication a){return s.addMember(id,x.email(),me(a));}}
